#include "PresetManager.h"
namespace cymbalforge { bool PresetManager::save(const juce::File& f,const CymbalParameters& p) { auto o=new juce::DynamicObject; auto add=[o](const char* n,const std::atomic<float>& v){o->setProperty(n,v.load());}; add("velocity",p.velocity);add("position",p.position);add("brightness",p.brightness);add("decay",p.decay);add("choke",p.choke);add("complexity",p.complexity);add("shimmer",p.shimmer);add("noise",p.noise);add("subLevel",p.subLevel);add("subTune",p.subTune);add("subDecay",p.subDecay);add("subDelay",p.subDelay);add("filterCutoff",p.filterCutoff);add("filterResonance",p.filterResonance);add("modLfoRate",p.modLfoRate);add("modLfoDepth",p.modLfoDepth);add("reverb",p.reverb);add("gain",p.gain); for(int i=0;i<4;++i){auto n=juce::String(i+1);o->setProperty("sample"+n+"Level",p.sampleLevel[(size_t)i].load());o->setProperty("sample"+n+"Tune",p.sampleTune[(size_t)i].load());o->setProperty("sample"+n+"Attack",p.sampleAttack[(size_t)i].load());o->setProperty("sample"+n+"Release",p.sampleRelease[(size_t)i].load());o->setProperty("sample"+n+"Delay",p.sampleDelay[(size_t)i].load());o->setProperty("sample"+n+"LfoRate",p.sampleLfoRate[(size_t)i].load());o->setProperty("sample"+n+"LfoDepth",p.sampleLfoDepth[(size_t)i].load());} o->setProperty("modes",p.modes.load());o->setProperty("model",p.model.load());o->setProperty("filterMode",p.filterMode.load());o->setProperty("modTarget",p.modTarget.load()); return f.replaceWithText(juce::JSON::toString(juce::var(o),true)); } bool PresetManager::load(const juce::File& f,CymbalParameters& p) { auto v=juce::JSON::parse(f);if(!v.isObject())return false;auto*o=v.getDynamicObject();auto set=[o](const char*n,std::atomic<float>&d){if(o->hasProperty(n))d.store(float(o->getProperty(n)));};set("velocity",p.velocity);set("position",p.position);set("brightness",p.brightness);set("decay",p.decay);set("choke",p.choke);set("complexity",p.complexity);set("shimmer",p.shimmer);set("noise",p.noise);set("subLevel",p.subLevel);set("subTune",p.subTune);set("subDecay",p.subDecay);set("subDelay",p.subDelay);set("filterCutoff",p.filterCutoff);set("filterResonance",p.filterResonance);set("modLfoRate",p.modLfoRate);set("modLfoDepth",p.modLfoDepth);set("reverb",p.reverb);set("gain",p.gain);for(int i=0;i<4;++i){auto n=juce::String(i+1);set(("sample"+n+"Level").toRawUTF8(),p.sampleLevel[(size_t)i]);set(("sample"+n+"Tune").toRawUTF8(),p.sampleTune[(size_t)i]);set(("sample"+n+"Attack").toRawUTF8(),p.sampleAttack[(size_t)i]);set(("sample"+n+"Release").toRawUTF8(),p.sampleRelease[(size_t)i]);set(("sample"+n+"Delay").toRawUTF8(),p.sampleDelay[(size_t)i]);set(("sample"+n+"LfoRate").toRawUTF8(),p.sampleLfoRate[(size_t)i]);set(("sample"+n+"LfoDepth").toRawUTF8(),p.sampleLfoDepth[(size_t)i]);}if(o->hasProperty("modes"))p.modes.store(int(o->getProperty("modes")));if(o->hasProperty("model"))p.model.store(int(o->getProperty("model")));if(o->hasProperty("filterMode"))p.filterMode.store(int(o->getProperty("filterMode")));if(o->hasProperty("modTarget"))p.modTarget.store(int(o->getProperty("modTarget")));return true;} }
